from modele import C,E

C('Mesurer et comparer des longueurs','Grandeurs et mesures','P1-P5',
 'Je choisis une unité et j’utilise les relations entre les unités.','Règle graduée, mètre et objets de la classe.',
 'Observe les graduations entre 0 et 1 cm sur la règle. Compte les millimètres. Compare une bande de 5 cm et 3 mm avec une bande de 52 mm.',
 ['1 cm = 10 mm ; 1 dm = 10 cm ; 1 m = 10 dm = 100 cm = 1 000 mm.','1 km = 1 000 m. Je choisis l’unité adaptée à la longueur.','Pour comparer ou additionner, j’exprime les longueurs dans la même unité en utilisant ces relations.'],
 '5 cm et 3 mm = 50 mm + 3 mm = 53 mm. Cette longueur dépasse 52 mm de 1 mm.',('segmentsmm',[53,72]),
 'Exprime 2 m et 35 cm en centimètres.','2 m = 200 cm ; 200 cm + 35 cm = 235 cm.',[
 E('Mesure les deux segments en millimètres. Vérifie l’échelle d’impression dans les outils.','A : 53 mm ; B : 72 mm.',('segmentsmm',[53,72])),
 E('Complète : 6 cm = … mm ; 3 dm = … cm ; 4 m = … cm.','60 mm ; 30 cm ; 400 cm.'),
 E('Exprime en mètres : 7 km ; 3 km et 250 m.','7 000 m ; 3 250 m.'),
 E('Exprime 248 cm en mètres et centimètres, puis en mètres, décimètres et centimètres.','2 m et 48 cm ; 2 m, 4 dm et 8 cm.'),
 E('Compare : 8 cm et 5 mm … 84 mm ; 2 m … 195 cm ; 4 km … 4 050 m.','> ; > ; <. 8 cm et 5 mm valent 85 mm.'),
 E('Trace un segment de 5 cm et 7 mm, puis un segment de 68 mm.','Les longueurs doivent être 57 mm et 68 mm, mesurées depuis zéro.'),
 E('Un ruban mesure 1 m. On en coupe 35 cm puis 28 cm. Quelle longueur reste ?','100 - 35 - 28 = 37 cm.',None,'100-35-28==37'),
 E('Choisis une unité adaptée : épaisseur d’une pièce ; longueur d’un cahier ; distance entre deux villes.','Par exemple mm ; cm ; km. Les estimations se discutent avec des objets réels.'),
 E('Lina dit que 5 cm et 4 mm font 9 mm. Explique et corrige.','Les unités diffèrent : 5 cm valent 50 mm. Le total est 54 mm.',None,'50+4==54')],
 'Comparer les unités sur une vraie règle et convertir par les relations connues.',
 'Ni tableau de conversion ni écriture à virgule des longueurs ne sont utilisés dans ce livre de cycle 2.')

C('Comprendre le périmètre','Grandeurs et mesures','P2-P5',
 'Je mesure la longueur du contour d’un polygone.','Ficelle, règle graduée et compas.',
 'Entoure un rectangle avec une ficelle, puis tends-la. Reporte aussi ses côtés bout à bout sur une droite avec le compas. Compare les longueurs obtenues.',
 ['Le périmètre est la longueur du contour d’une figure.','Pour un polygone, je réunis les longueurs de tous ses côtés.','Dans un rectangle, les côtés opposés ont la même longueur ; je peux éviter de tous les mesurer.'],
 'Pour un rectangle de côtés 6 cm et 3 cm, le contour mesure 6 cm + 3 cm + 6 cm + 3 cm = 18 cm.',('perirect',[6,3]),
 'Un carré a des côtés de 4 cm. Cherche son périmètre en racontant le contour.','4 cm + 4 cm + 4 cm + 4 cm = 16 cm.',[
 E('Calcule le périmètre du rectangle représenté.','6 + 3 + 6 + 3 = 18 cm.',('perirect',[6,3]),'6+3+6+3==18'),
 E('Un triangle a des côtés de 4 cm, 5 cm et 6 cm. Quel est son périmètre ?','4 + 5 + 6 = 15 cm.',None,'4+5+6==15'),
 E('Un carré a des côtés de 7 cm. Quelle est la longueur de son contour ?','7 + 7 + 7 + 7 = 28 cm.',None,'7+7+7+7==28'),
 E('Mesure les trois côtés du triangle et trouve son périmètre. Imprime à 100 %.','Côtés : 3 cm, 4 cm et 5 cm ; périmètre : 12 cm.',('peritriangle',None),'3+4+5==12'),
 E('Un rectangle a des côtés de 8 cm et de 25 mm. Exprime son périmètre en millimètres.','80 + 25 + 80 + 25 = 210 mm.',None,'80+25+80+25==210'),
 E('Un rectangle de 6 cm sur 4 cm et un carré de côté 5 cm ont-ils le même périmètre ?','Oui : 6 + 4 + 6 + 4 = 20 cm et 5 + 5 + 5 + 5 = 20 cm.',None,'6+4+6+4==5+5+5+5==20'),
 E('Un jardin rectangulaire a des côtés de 12 m et 8 m. On laisse une ouverture de 2 m. Quelle longueur de clôture faut-il ?','Contour : 40 m ; clôture : 40 - 2 = 38 m.',None,'12+8+12+8-2==38'),
 E('Sur ta feuille, dessine deux polygones différents qui ont chacun un périmètre de 16 cm.','Par exemple un carré de côté 4 cm et un rectangle de côtés 5 cm et 3 cm.'),
 E('Noé additionne seulement 6 et 3 pour le rectangle de l’exemple. Explique ce qui manque.','Il a parcouru deux côtés sur quatre. Il manque encore 6 cm et 3 cm.')],
 'Faire suivre le contour du doigt et marquer chaque côté après l’avoir pris en compte.',
 'Aucune formule de périmètre n’est à mémoriser ici ; on s’appuie sur le contour et les propriétés des côtés.')

C('Comparer des masses : g, kg et t','Grandeurs et mesures','P1-P5',
 'Je pèse, j’estime et je relie grammes, kilogrammes et tonnes.','Balance et masses marquées.',
 'Équilibre une masse de 1 kg avec des masses de 100 g. Combien en faut-il ? Compare ensuite les masses indiquées sur plusieurs emballages.',
 ['1 kg = 1 000 g ; 1 t = 1 000 kg.','Pour comparer des masses, je les exprime dans une même unité.','J’estime avec des repères : une petite pomme se mesure en g, une personne en kg, un camion en t.'],
 '2 kg et 350 g = 2 350 g. Cette masse est supérieure à 2 305 g.',('masscards',['250 g','1 kg','2 t']),
 'Exprime 4 280 g en kilogrammes et grammes.','4 kg et 280 g.',[
 E('Complète : 3 kg = … g ; 5 t = … kg ; 7 000 g = … kg.','3 000 g ; 5 000 kg ; 7 kg.'),
 E('Exprime 6 450 g en kilogrammes et grammes, puis 3 080 kg en tonnes et kilogrammes.','6 kg et 450 g ; 3 t et 80 kg.'),
 E('Compare : 2 kg et 75 g … 2 750 g ; 4 t … 3 980 kg.','< ; >. 2 kg et 75 g valent 2 075 g.'),
 E('Range du plus léger au plus lourd : 1 250 g ; 2 kg ; 950 g ; 1 kg et 50 g.','950 g < 1 kg et 50 g < 1 250 g < 2 kg.'),
 E('Choisis une unité : une feuille de papier ; la masse d’un adulte ; la masse d’un camion.','g ; kg ; t.'),
 E('Une balance s’équilibre avec 500 g, 200 g et 50 g. Quelle est la masse de l’objet ?','750 g.',('massweights',[500,200,50]),'500+200+50==750'),
 E('Un sac pèse 2 kg. On en retire 650 g. Quelle masse reste dans le sac, si le sac vide est négligé ?','2 000 - 650 = 1 350 g, soit 1 kg et 350 g.',None,'2000-650==1350'),
 E('Trois cartons pèsent chacun 750 g. Quelle est leur masse totale en g, puis en kg et g ?','2 250 g, soit 2 kg et 250 g.',None,'3*750==2250'),
 E('Lina dit que 1 kg et 8 g font 1 800 g. Corrige et explique.','1 kg et 8 g valent 1 008 g ; 1 800 g correspondent à 1 kg et 800 g.')],
 'Faire peser des objets et manipuler les masses avant de convertir les écritures.',
 'On estime une masse avec une unité et un repère ; la taille visuelle d’un objet ne suffit pas à connaître sa masse.')

C('Mesurer des contenances','Grandeurs et mesures','P2-P5',
 'Je compare des récipients et j’utilise L, dL et cL.','Eau, récipients et verre gradué, avec l’adulte.',
 'Transvase un litre d’eau dans des petits récipients de 10 cL. Compte combien il en faut. Compare deux bouteilles de formes différentes par transvasement.',
 ['La contenance indique la quantité de liquide qu’un récipient peut contenir.','1 L = 10 dL = 100 cL ; 1 dL = 10 cL.','La hauteur d’un récipient ne suffit pas pour comparer : je peux transvaser ou mesurer.'],
 '2 L et 35 cL = 200 cL + 35 cL = 235 cL. Un verre de 20 cL remplit un litre en cinq versements.',('capacity',[100,60]),
 'Exprime 3 L et 4 dL en centilitres.','300 cL + 40 cL = 340 cL.',[
 E('Complète : 4 L = … cL ; 6 dL = … cL ; 2 L = … dL.','400 cL ; 60 cL ; 20 dL.'),
 E('Lis la quantité indiquée dans chaque verre gradué.','A : 100 cL ; B : 60 cL.',('capacity',[100,60])),
 E('Exprime 780 cL en litres et centilitres.','7 L et 80 cL.'),
 E('Compare : 1 L … 90 cL ; 3 dL … 35 cL ; 2 L et 5 cL … 250 cL.','> ; < ; <. 2 L et 5 cL valent 205 cL.'),
 E('Range : 75 cL ; 1 L ; 8 dL ; 2 L.','75 cL < 8 dL < 1 L < 2 L.'),
 E('Combien de verres de 25 cL peut-on remplir avec 1 L ?','4 verres.',None,'100//25==4'),
 E('Un arrosoir contient 3 L d’eau. On utilise 125 cL. Combien reste-t-il en cL ?','300 - 125 = 175 cL.',None,'300-125==175'),
 E('Choisis une contenance plausible : un verre, 20 cL ou 20 L ? Un arrosoir, 10 cL ou 10 L ?','Un verre : 20 cL ; un arrosoir : 10 L.'),
 E('Noé affirme qu’une bouteille haute contient toujours plus qu’une bouteille basse. Propose une vérification.','Transvaser dans le même récipient gradué ou compter les mêmes verres remplis. La largeur compte aussi.')],
 'Utiliser le même verre étalon et un récipient gradué. Faire verbaliser les équivalences.',
 'Les quantités de ce chapitre restent en unités entières ou composées ; on n’utilise pas d’écriture à virgule pour les contenances.')

C('Comprendre les prix en euros','Monnaie','Dès P1',
 'Je lis les prix à virgule et je rends la monnaie par compléments.','Monnaie de jeu et étiquettes de prix.',
 'Construis 2,05 € puis 2,50 € avec la monnaie de jeu. Échange des pièces pour écrire chaque somme en centimes. Compare les deux prix.',
 ['1 € = 100 centimes. La virgule aide à repérer le chiffre des euros à l’unité.','2,05 € signifie 2 euros et 5 centimes ; 2,50 € signifie 2 euros et 50 centimes.','Pour rendre la monnaie, je peux compléter le prix jusqu’à la somme donnée.'],
 'Pour un achat de 3,68 € payé avec 5 € : 32 centimes pour atteindre 4 €, puis 1 € ; monnaie : 1,32 €.',('pricepair',None),
 'Construis 4,07 € avec de la monnaie de jeu.','Par exemple deux pièces de 2 €, une de 5 centimes et une de 2 centimes.',[
 E('Écris avec une virgule : 3 euros et 8 centimes ; 12 euros et 50 centimes.','3,08 € ; 12,50 €.'),
 E('Exprime en centimes : 4,25 € ; 7,03 € ; 10 €.','425 centimes ; 703 centimes ; 1 000 centimes.'),
 E('Exprime en euros avec une virgule : 508 centimes ; 1 260 centimes.','5,08 € ; 12,60 €.'),
 E('Compare : 6,05 € … 6,50 € ; 4,80 € … 480 centimes.','< ; =.'),
 E('Construis 3,75 € avec le moins de pièces possible, parmi les pièces de jeu usuelles.','2 € + 1 € + 50 c + 20 c + 5 c : 5 pièces.'),
 E('Un objet coûte 4,65 €. Tu paies avec 5 €. Quelle monnaie reçoit-on ?','35 centimes, soit 0,35 €.',None,'500-465==35'),
 E('Un livre coûte 7,85 €. Tu donnes 10 €. Rends la monnaie par compléments.','15 centimes pour atteindre 8 €, puis 2 € : 2,15 €.',None,'1000-785==215'),
 E('Range les prix : 8,09 € ; 8,90 € ; 8,50 € ; 8,05 €.','8,05 € < 8,09 € < 8,50 € < 8,90 €.'),
 E('Lina lit 9,06 € comme neuf euros et soixante centimes. Explique et corrige.','C’est neuf euros et six centimes. Neuf euros et soixante centimes s’écrit 9,60 €.')],
 'Construire chaque prix avec les pièces et écrire le total en centimes.',
 'Les nombres à virgule sont travaillés dans le contexte concret de la monnaie ; les unités décimales abstraites relèvent du cycle 3.')

C('Poser les calculs en euros','Monnaie et calcul','Addition P2 au plus tard ; soustraction P4 au plus tard',
 'J’additionne et je soustrais des montants en alignant les euros et les centimes.','Papier quadrillé et monnaie de jeu.',
 'Réunis 12,75 € et 4,60 € avec la monnaie de jeu. Échange 100 centimes contre 1 €. Relie cet échange à la retenue de l’addition posée.',
 ['J’aligne les virgules pour placer les euros sous les euros et les centimes sous les centimes.','Je peux écrire 8 € sous la forme 8,00 € pour poser le calcul.','Je calcule comme avec des entiers en gardant les rangs, puis je vérifie avec les centimes ou la monnaie de jeu.'],
 '12,75 € + 4,60 € = 17,35 €. En centimes : 1 275 + 460 = 1 735.',('eurocolumn',['12,75','4,60','+']),
 'Pose 10 € - 3,65 €. Vérifie en centimes.','10,00 € - 3,65 € = 6,35 € ; 1 000 - 365 = 635 centimes.',[
 E('Pose et calcule 4,56 € + 15,30 €.','19,86 €.',('euroblank','+'),'456+1530==1986'),
 E('Pose et calcule 43,45 € + 68 €.','111,45 €. Écrire 68,00 €.',None,'4345+6800==11145'),
 E('Pose et calcule 7,85 € + 68 centimes.','8,53 €. Écrire 0,68 € pour le deuxième montant.',None,'785+68==853'),
 E('Pose et calcule 14 € + 3,67 € + 54 centimes.','18,21 €.',None,'1400+367+54==1821'),
 E('Pose et calcule 24,56 € - 15,30 €.','9,26 €.',('euroblank','-'),'2456-1530==926'),
 E('Pose et calcule 74,36 € - 12,50 €.','61,86 €.',None,'7436-1250==6186'),
 E('Une classe achète un jeu à 18,75 € et un album à 9,85 €. Quel est le prix total ?','28,60 €.',None,'1875+985==2860'),
 E('Tu achètes un objet à 12,45 € et un autre à 6,80 €. Tu donnes 20 €. Quelle monnaie reçoit-on ?','Achats : 19,25 € ; monnaie : 0,75 €.',None,'1245+680==1925 and 2000-1925==75'),
 E('Noé aligne 68 centimes comme 68 euros sous 7,85 €. Explique la bonne disposition.','68 centimes s’écrit 0,68 €. Les virgules doivent être alignées ; la somme vaut 8,53 €.')],
 'Revenir aux montants en centimes et relier les échanges à la monnaie de jeu.',
 'L’écriture de deux chiffres de centimes aide l’alignement. Les sommes en centimes peuvent dépasser 10 000 dans un calcul posé de prix.')
